python3 - <<'PY'
import re
p='bench/heaps_test.adb'
s=open(p).read()

# The spec already declares them; drop the forward declarations the body inherited.
for n,sig in [('Test_Arena','(N : Positive)'),('Test_Arena_Churn','(N : Positive)'),
              ('Test_Arena_Meld','(N, M : Natural)'),('Test_Arena_KWay','(N, Ways : Positive)')]:
    s=s.replace('      procedure %s %s;\n      procedure %s %s is'%(n,sig,n,sig),
                '      procedure %s %s is'%(n,sig),1)

s=s.replace('      with procedure Meld (T : in out Extended_Index; U : in out Extended_Index);',
            '      with procedure Meld\n        (T : in out Extended_Index; U : in out Extended_Index);')

s=s.replace("""   --  The arena: several trees sharing one pool. Heaps.Leftist_Pool is a
   --  library-level instance of it, so the pool is package state rather than
   --  an object, and every test below calls Clear first -- that, and nothing
   --  else, is what keeps them independent of one another.""",
"""   --  The arenas: several trees sharing one pool. There are two of them now,
   --  the leftist and the skew, and they differ in nothing this suite can see
   --  -- same interface, same contracts, same claims about the free chain and
   --  about the trees an operation does not name -- so the tests below are
   --  written once as a generic and run once per arena. A pool is package
   --  state rather than an object, so every test calls Clear first; that, and
   --  nothing else, is what keeps them independent of one another.""")

s=s.replace("with Heaps.Sorted;","with Heaps.Skew_Pool;\nwith Heaps.Sorted;")
s=s.replace("   package Arena renames Heaps.Leftist_Pool;",
            "   package Arena renames Heaps.Leftist_Pool;\n   package Skew_Arena renames Heaps.Skew_Pool;")

# Main body: drive both instances.
s=s.replace("""   for N of Churn_Sizes loop
      Test_Arena_Churn (N);
   end loop;""",
"""   for N of Churn_Sizes loop
      Leftist_Suite.Test_Arena_Churn (N);
      Skew_Suite.Test_Arena_Churn (N);
   end loop;""")
s=s.replace("      Test_Arena (N);\n","      Leftist_Suite.Test_Arena (N);\n      Skew_Suite.Test_Arena (N);\n")
s=s.replace("""      Test_Arena_Meld (N, N);
      Test_Arena_Meld (N, 1);
      Test_Arena_Meld (1, N);
      Test_Arena_Meld (N, 0);
      Test_Arena_Meld (0, N);
      Test_Arena_KWay (N, 16);
   end loop;
   Test_Arena_Meld (0, 0);
   Test_Arena_KWay (1, 16);""",
"""      for Suite in 1 .. 2 loop
         declare
            procedure Arena_Meld (A, B : Natural);
            procedure Arena_Meld (A, B : Natural) is
            begin
               if Suite = 1 then
                  Leftist_Suite.Test_Arena_Meld (A, B);
               else
                  Skew_Suite.Test_Arena_Meld (A, B);
               end if;
            end Arena_Meld;
         begin
            Arena_Meld (N, N);
            Arena_Meld (N, 1);
            Arena_Meld (1, N);
            Arena_Meld (N, 0);
            Arena_Meld (0, N);

            if Suite = 1 then
               Leftist_Suite.Test_Arena_KWay (N, 16);
            else
               Skew_Suite.Test_Arena_KWay (N, 16);
            end if;
         end;
      end loop;
   end loop;
   Leftist_Suite.Test_Arena_Meld (0, 0);
   Skew_Suite.Test_Arena_Meld (0, 0);
   Leftist_Suite.Test_Arena_KWay (1, 16);
   Skew_Suite.Test_Arena_KWay (1, 16);""")
open(p,'w').write(s)
PY
gprbuild -P bench.gpr -q 2>&1 | head -30

